// Parse JSON từ AI output
const eventData = JSON.parse($input.first().json.output);

// Function để chuyển UTC+7 về UTC (trừ 7 giờ)
function convertToUTC(timeString) {
  const date = new Date(timeString + '+07:00'); // Thêm timezone +07:00
  return date.toISOString().slice(0, 19).replace('T', ' '); // Format về YYYY-MM-DD HH:MM:SS
}

// Convert start và stop time về UTC nếu cần
if (eventData.start) {
  eventData.start = convertToUTC(eventData.start);
}
if (eventData.stop) {
  eventData.stop = convertToUTC(eventData.stop);
}

// Tính duration nếu chưa có
if (!eventData.duration && eventData.start && eventData.stop) {
  const startTime = new Date(eventData.start);
  const stopTime = new Date(eventData.stop);
  eventData.duration = (stopTime - startTime) / (1000 * 60 * 60); // Convert to hours
}

return eventData;

// Format response cho user
const result = $input.first().json;

return {
  success: true,
  message: `Đã tạo thành công sự kiện: ${result.name}`,
  event_id: result.id,
  event_data: {
    name: result.name,
    start: result.start,
    stop: result.stop,
    duration: result.duration,
    location: result.location || '',
    description: result.description || ''
  }
};
